// tabs
document.querySelectorAll('[data-tabs]').forEach(function(g){
  var tabs=g.querySelectorAll('.tab'),panels=g.querySelectorAll('.panel');
  tabs.forEach(function(t,i){t.addEventListener('click',function(){
    tabs.forEach(function(x){x.setAttribute('aria-selected','false')});
    panels.forEach(function(p){p.classList.remove('on')});
    t.setAttribute('aria-selected','true');panels[i].classList.add('on');
    restart(panels[i].querySelector('.flow'));
  })});
});
function restart(f){if(!f)return;f.classList.remove('run');void f.offsetWidth;f.classList.add('run')}
// stagger flow animations
document.querySelectorAll('.flow').forEach(function(f){
  var lines=f.querySelectorAll('.doc .ln'),rows=f.querySelectorAll('.erp .row');
  rows.forEach(function(r,i){r.style.animationDelay=(0.35+i*0.45)+'s'});var ft=f.querySelector('.erp .foot');if(ft)ft.style.animationDelay=(0.6+rows.length*0.45)+'s';
  lines.forEach(function(l,i){
    var d=(0.15+i*0.42);l.style.animation='none';
    setTimeout(function(){},0);
    l.dataset.d=d;
  });
});
// line highlight via JS loop (keeps sync with scan)
function pulse(f){
  var lines=f.querySelectorAll('.doc .ln');var i=0;
  clearInterval(f._t);
  f._t=setInterval(function(){
    lines.forEach(function(l){l.style.background='transparent'});
    if(i<lines.length){lines[i].style.background='rgba(99,91,255,.10)';lines[i].style.transition='background .25s'}
    i=(i+1)%(lines.length+6);
  },420);
}
document.querySelectorAll('.flow').forEach(pulse);
// reveal
var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.12});
document.querySelectorAll('.reveal').forEach(function(el){io.observe(el)});
// roi
(function(){
  var r=document.getElementById('roi');if(!r)return;
  var q=function(id){return document.getElementById(id)};
  var rate=parseFloat(r.dataset.auto||'0.8');
  function fmt(n){return n.toLocaleString('en-US',{maximumFractionDigits:0})}
  function calc(){
    var v=+q('rv').value,m=+q('rm').value,c=+q('rc').value;
    q('ov').textContent=fmt(v);q('om').textContent=m+' min';q('oc').textContent='$'+c;
    var hrs=v*m/60*rate,yr=hrs*c*12,fte=hrs/160;
    q('oh').textContent=fmt(hrs);q('oy').textContent='$'+fmt(yr);q('of').textContent=fte.toFixed(1);
  }
  ['rv','rm','rc'].forEach(function(id){q(id).addEventListener('input',calc)});calc();
})();
// demo form -> instant scheduling step
(function(){
  var f=document.getElementById('demoform');if(!f)return;
  f.addEventListener('submit',function(e){
    e.preventDefault();
    if(!f.checkValidity()){f.reportValidity();return}
    // TODO(dev): POST to HubSpot Forms API here, then load HubSpot Meetings / Chili Piper router.
    f.querySelector('.fields').style.display='none';
    var s=f.querySelector('.slots');s.classList.add('on');
    var g=s.querySelector('.grid');g.innerHTML='';
    var d=new Date(),n=0;
    while(n<6){d.setDate(d.getDate()+1);var w=d.getDay();if(w===0||w===6)continue;
      [10,15].forEach(function(h){if(n>=6)return;var b=document.createElement('button');b.type='button';
        b.textContent=d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})+' · '+(h>12?h-12:h)+(h>=12?' PM':' AM')+' CT';
        b.onclick=function(){g.querySelectorAll('button').forEach(function(x){x.classList.remove('sel')});b.classList.add('sel');s.querySelector('.conf').style.display='block'};
        g.appendChild(b);n++});
    }
  });
})();
// sticky cta after hero
(function(){var s=document.querySelector('.sticky'),h=document.querySelector('.hero'),d=document.getElementById('demo');if(!s||!h)return;
  window.addEventListener('scroll',function(){var y=window.scrollY,dt=d.getBoundingClientRect().top;
    s.classList.toggle('show',y>h.offsetHeight-60&&dt>window.innerHeight)},{passive:true});})();

(function(){
  var WORDS=["catch a failing mill cert", "remember every customer\u2019s habits", "price quotes from your win history", "hold invoices that don\u2019t add up", "spot short-pay patterns"],DUR=5500;
  var chips=[].slice.call(document.querySelectorAll('.uc')),views=[].slice.call(document.querySelectorAll('.hv'));
  var i=0,paused=0;
  function show(n,user){
    i=n;chips.forEach(function(c,k){c.classList.toggle('on',k===n);c.classList.remove('play')});
    views.forEach(function(v,k){v.classList.toggle('on',k===n)});
    var f=views[n].querySelector('.flow');restart(f);pulse(f);
    var c=chips[n];void c.offsetWidth;if(!user)c.classList.add('play');
    var r=document.querySelector('.hero.sc .rot');
    if(r){r.classList.add('out');setTimeout(function(){r.querySelector('em').textContent=WORDS[n];r.classList.remove('out')},300)}
  }
  chips.forEach(function(c,k){c.addEventListener('click',function(){paused=Date.now()+15000;show(k,true)})});
  show(0);setInterval(function(){if(Date.now()>=paused)show((i+1)%views.length)},DUR);
  // count-up on the $582,000 figure
  var to=document.querySelector('.hc-num .to');
  if(to&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
    var end=+to.dataset.to,start=+to.dataset.from,t0=null;
    function step(ts){if(!t0)t0=ts;var p=Math.min((ts-t0)/1600,1),e=1-Math.pow(1-p,3);
      to.textContent=to.dataset.pre+Math.round(start+(end-start)*e).toLocaleString('en-US')+to.dataset.suf;if(p<1)requestAnimationFrame(step)}
    setTimeout(function(){requestAnimationFrame(step)},900);
  }
})();
